(5770408, 839808, 112828, '<td valign="top">He looks aggressive, not bored...  Really nice comp though.</td>', 'He looks aggressive, not bored...  Really nice comp though.', '2009-12-17 14:53:33.000000', NULL, 1),
(5770410, 839579, 112828, '<td valign="top">EEH!@ Gads!  This should seriously have gone into the Halloween challenge...  Might I suggest a re-shoot on this theme in just under a year?<br/> <br/>You get a mid-high score.</td>', 'EEH!@ Gads!  This should seriously have gone into the Halloween challenge...  Might I suggest a re-shoot on this theme in just under a year? You get a mid-high score.', '2009-12-17 14:55:05.000000', NULL, 1),
(5770419, 839983, 91197, '<td valign="top">Strange shot. Moody. I like the low key effect. Nice DOF but, I d like to see the scissors more in focus though. I am not sure if it fits with "Bored". Anyways nice catch! 7.</td>', 'Strange shot. Moody. I like the low key effect. Nice DOF but, I d like to see the scissors more in focus though. I am not sure if it fits with "Bored". Anyways nice catch! 7.', '2009-12-17 15:06:51.000000', NULL, 1),
(5770588, 839982, 112107, '<td valign="top">Excelent use of B&amp;W. It trully makes the picture.</td>', 'Excelent use of B&W. It trully makes the picture.', '2009-12-17 17:57:09.000000', NULL, 1),
(5770608, 839720, 112107, '<td valign="top">Good idea but somehow the composition fails, don''t ask me how...</td>', 'Good idea but somehow the composition fails, don''t ask me how...', '2009-12-17 18:09:20.000000', NULL, 1),
(5770610, 840146, 112107, '<td valign="top">Extra points for the title.</td>', 'Extra points for the title.', '2009-12-17 18:10:39.000000', NULL, 1),
(5770613, 839449, 112107, '<td valign="top">Wow! A good pet photo!</td>', 'Wow! A good pet photo!', '2009-12-17 18:11:42.000000', NULL, 1),
(5770620, 838609, 112107, '<td valign="top">I like the composition but the shadows distress me.</td>', 'I like the composition but the shadows distress me.', '2009-12-17 18:16:15.000000', NULL, 1),
(5770627, 839702, 112107, '<td valign="top">Great lighting.</td>', 'Great lighting.', '2009-12-17 18:18:23.000000', NULL, 1),
(5770632, 840145, 112107, '<td valign="top">I liked this photo, but why the borders? Wouldn''t a frame work better?</td>', 'I liked this photo, but why the borders? Wouldn''t a frame work better?', '2009-12-17 18:23:18.000000', NULL, 1),
(5770636, 839398, 112107, '<td valign="top">Another good pet photo.</td>', 'Another good pet photo.', '2009-12-17 18:24:39.000000', NULL, 1),
(5770638, 840084, 112107, '<td valign="top">Great composition. An instant classic.<br/>The only thing keeping me from rating it 10* is a fishy perspective. <br/>What''s going on? Anyway the characters almost hide it.</td>', 'Great composition. An instant classic.The only thing keeping me from rating it 10* is a fishy perspective. What''s going on? Anyway the characters almost hide it.', '2009-12-17 18:26:16.000000', NULL, 1),
(5770639, 840023, 112107, '<td valign="top">Great photo. PP really makes it work.</td>', 'Great photo. PP really makes it work.', '2009-12-17 18:26:25.000000', NULL, 1),
(5770661, 839449, 88850, '<td valign="top">Since I have a Weim I know this look very well!  You got a 10 from me but I might be biased. ;^)</td>', 'Since I have a Weim I know this look very well!  You got a 10 from me but I might be biased. ;^)', '2009-12-17 18:54:55.000000', NULL, 1),
(5770677, 840019, 99708, '<td valign="top">I like the concept of the subject, just not sure if having this picture in b&amp;W was the best idea.  It seems a tad to dark.</td>', 'I like the concept of the subject, just not sure if having this picture in b&W was the best idea.  It seems a tad to dark.', '2009-12-17 19:21:52.000000', NULL, 1),
(5770678, 839983, 99708, '<td valign="top">I don''t get it.  Sorry.</td>', 'I don''t get it.  Sorry.', '2009-12-17 19:26:39.000000', NULL, 1),
(5770701, 839925, 99708, '<td valign="top">This one could have also worked under the other challenge.</td>', 'This one could have also worked under the other challenge.', '2009-12-17 19:55:17.000000', NULL, 1),
(5770702, 838561, 99708, '<td valign="top">I think he looks a bit more peeved than bored.</td>', 'I think he looks a bit more peeved than bored.', '2009-12-17 19:57:03.000000', NULL, 1),
(5770713, 839998, 101256, '<td valign="top">A lovely portrait. Not exactly sure how it fits the criteria, but it''s still engaging. Well done.</td>', 'A lovely portrait. Not exactly sure how it fits the criteria, but it''s still engaging. Well done.', '2009-12-17 20:19:23.000000', NULL, 1),
(5770714, 840080, 101256, '<td valign="top">I like this - can''t really explain why, but it intrigues me.  Very different look at the subject matter.</td>', 'I like this - can''t really explain why, but it intrigues me.  Very different look at the subject matter.', '2009-12-17 20:20:01.000000', NULL, 1),
(5770716, 839925, 101256, '<td valign="top">A terrific capture - nicely composed and very true to the second stringer''s atheletic careers.  Well done.</td>', 'A terrific capture - nicely composed and very true to the second stringer''s atheletic careers.  Well done.', '2009-12-17 20:21:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5770718, 840023, 101256, '<td valign="top">A great idea, but it appears to be a little darker than necessary to be truly effective.  A good solid effort though.  I like the motion capture, although I might have preferred to see a little more of the hands. Solid effort.</td>', 'A great idea, but it appears to be a little darker than necessary to be truly effective.  A good solid effort though.  I like the motion capture, although I might have preferred to see a little more of the hands. Solid effort.', '2009-12-17 20:23:22.000000', NULL, 1),
(5770719, 839465, 101256, '<td valign="top">Great concept - it''s either tossing popcorn or chucking pencils into the ceiling. :&gt;) Nice color, effective motion capture.  The flash shadows are a little distracting but not enough to negatively impact the overall image. Nice job.</td>', 'Great concept - it''s either tossing popcorn or chucking pencils into the ceiling. :>) Nice color, effective motion capture.  The flash shadows are a little distracting but not enough to negatively impact the overall image. Nice job.', '2009-12-17 20:25:15.000000', NULL, 1),
(5770720, 840076, 101256, '<td valign="top">Bored and apparently unhappy about it. Lots of detail in that face - the clarity is startling.  Very well done.</td>', 'Bored and apparently unhappy about it. Lots of detail in that face - the clarity is startling.  Very well done.', '2009-12-17 20:26:16.000000', NULL, 1),
(5770723, 839398, 101256, '<td valign="top">Got a very nice chuckle out of this - poor little dog - all that excitement and not a piece of human food in sight. Love it - well done.</td>', 'Got a very nice chuckle out of this - poor little dog - all that excitement and not a piece of human food in sight. Love it - well done.', '2009-12-17 20:27:24.000000', NULL, 1),
(5770728, 838989, 101256, '<td valign="top">Not something normally seen - a domestic goose hanging with Canadian geese. Not exactly sure what the title does for the image, but then I''m being normally dense.  It''s a good image, but a little average in terms of subject.<br/>Still, a nice capture.</td>', 'Not something normally seen - a domestic goose hanging with Canadian geese. Not exactly sure what the title does for the image, but then I''m being normally dense.  It''s a good image, but a little average in terms of subject.Still, a nice capture.', '2009-12-17 20:30:25.000000', NULL, 1),
(5770730, 840040, 101256, '<td valign="top">Overall, the image seems a little flat to me and overly gray. There appears to be some detail in the clouds that could have been brought out a little better which would have provided some depth and detail to contrast with the overly busy bare tree branches.  I also think the image is a little too tall a little more crop of the branches out of the image to concentrate on the subject would have helped a lot in my opinion.  Still, a good capture and great title.</td>', 'Overall, the image seems a little flat to me and overly gray. There appears to be some detail in the clouds that could have been brought out a little better which would have provided some depth and detail to contrast with the overly busy bare tree branches.  I also think the image is a little too tall a little more crop of the branches out of the image to concentrate on the subject would have helped a lot in my opinion.  Still, a good capture and great title.', '2009-12-17 20:32:58.000000', NULL, 1),
(5770731, 839714, 101256, '<td valign="top">There are two ways of looking at this - one, an experiment in exposure and a different look at how color affects mood and impression or as a whoopsie in which the author obviously is thinking so far outside the box that the viewer wonders why it was submitted.  I''ll take the former - interesting image and effect.</td>', 'There are two ways of looking at this - one, an experiment in exposure and a different look at how color affects mood and impression or as a whoopsie in which the author obviously is thinking so far outside the box that the viewer wonders why it was submitted.  I''ll take the former - interesting image and effect.', '2009-12-17 20:35:01.000000', NULL, 1),
(5770743, 839324, 101256, '<td valign="top">I had to come back to this a couple of times to be totally fair.  This may work for some, but the overall washed out semi-monotone effect seems to be overdone.  I understand the choice and it''s a good idea, but it''s just a tad over the top and not effective. Technically, it''s a good image and I like the use of DOF to enhance the effect.</td>', 'I had to come back to this a couple of times to be totally fair.  This may work for some, but the overall washed out semi-monotone effect seems to be overdone.  I understand the choice and it''s a good idea, but it''s just a tad over the top and not effective. Technically, it''s a good image and I like the use of DOF to enhance the effect.', '2009-12-17 20:45:43.000000', NULL, 1),
(5770747, 839856, 101256, '<td valign="top">Good idea, very nicely detailed and fairly effective. A hard subject to properly capture, but the author has done well here.</td>', 'Good idea, very nicely detailed and fairly effective. A hard subject to properly capture, but the author has done well here.', '2009-12-17 20:46:40.000000', NULL, 1),
(5770749, 839840, 101256, '<td valign="top">Another laugh out loud image - great detail, nice color balance and funny title. Overall a great capture and title - very effective.  Well done.</td>', 'Another laugh out loud image - great detail, nice color balance and funny title. Overall a great capture and title - very effective.  Well done.', '2009-12-17 20:47:42.000000', NULL, 1),
(5770755, 838661, 101256, '<td valign="top">Intriguing portrait.  Could be looked at as an "after" party image when you''ve reached that washed out, no mas state that sometimes follows a rousing good time. Extra point for concept and execution.  Well done.</td>', 'Intriguing portrait.  Could be looked at as an "after" party image when you''ve reached that washed out, no mas state that sometimes follows a rousing good time. Extra point for concept and execution.  Well done.', '2009-12-17 20:50:07.000000', NULL, 1),
(5770758, 840019, 101256, '<td valign="top">As a retired mathematician I can well understand.  Then again, arithmetic makes the world go ''round so to speak.  I like the conversion as nothing is overly done and it all works together in harmony. Very nice capture - well done.</td>', 'As a retired mathematician I can well understand.  Then again, arithmetic makes the world go ''round so to speak.  I like the conversion as nothing is overly done and it all works together in harmony. Very nice capture - well done.', '2009-12-17 20:52:03.000000', NULL, 1),
(5770773, 839838, 101256, '<td valign="top">I had a hard time with this because the capture indicates an emotion that extends beyond boredom - almost into despair or depression. However, boredom is a component of depression so it does work. After thinking about it for a while, I''ve concluded that so far, it''s the best that I''ve seen in this challenge and worthy of ribbon consideration.  Technically and artistically competant with a strong visual and emotional impact.  A favorite. Well done.</td>', 'I had a hard time with this because the capture indicates an emotion that extends beyond boredom - almost into despair or depression. However, boredom is a component of depression so it does work. After thinking about it for a while, I''ve concluded that so far, it''s the best that I''ve seen in this challenge and worthy of ribbon consideration.  Technically and artistically competant with a strong visual and emotional impact.  A favorite. Well done.', '2009-12-17 21:13:52.000000', NULL, 1),
(5770776, 839720, 101256, '<td valign="top">Bored or frustrated?  Half true if the rumors I''ve heard are true. Visually interesting via the interesting angle chosen. An excellant submission - well done.</td>', 'Bored or frustrated?  Half true if the rumors I''ve heard are true. Visually interesting via the interesting angle chosen. An excellant submission - well done.', '2009-12-17 21:14:59.000000', NULL, 1),
(5770777, 839579, 101256, '<td valign="top">When I first looked at this I thought "where did the author find a real Zombie".  :&gt;) Very interesting look at the subject matter - a good solid composition technically competant and artistically intriguing.  Well done.</td>', 'When I first looked at this I thought "where did the author find a real Zombie".  :>) Very interesting look at the subject matter - a good solid composition technically competant and artistically intriguing.  Well done.', '2009-12-17 21:16:34.000000', NULL, 1),
(5770780, 839529, 101256, '<td valign="top">Ok - I''ll admit it - I''m baffled.  Perhaps a statement of running out of challenge ideas for capture? If so, it works so I''ll go with it. Out of the box thinking is always appreciated. Well done.</td>', 'Ok - I''ll admit it - I''m baffled.  Perhaps a statement of running out of challenge ideas for capture? If so, it works so I''ll go with it. Out of the box thinking is always appreciated. Well done.', '2009-12-17 21:18:21.000000', NULL, 1),
(5770782, 839417, 101256, '<td valign="top">This is an incredible image both from an artistic standpoint as well as the technical.  The very compatiable color mix, intricate detail and different subject matter taken at a different angle all work no matter what the subject matter. An excellent entry and one that I wish I could have taken. A clear example of proper exposure, color and lighting in addition to subject matter.  A worthy contender for a ribbon - one of the few I''ve seen in this challenge.  Well done.</td>', 'This is an incredible image both from an artistic standpoint as well as the technical.  The very compatiable color mix, intricate detail and different subject matter taken at a different angle all work no matter what the subject matter. An excellent entry and one that I wish I could have taken. A clear example of proper exposure, color and lighting in addition to subject matter.  A worthy contender for a ribbon - one of the few I''ve seen in this challenge.  Well done.', '2009-12-17 21:20:55.000000', NULL, 1),
(5770783, 839971, 101256, '<td valign="top">Interesting effect here.  The can itself is intriguing, but the mismatched boots on the worked in the background immediately attracts the eye. Very clever capture even if unintended.</td>', 'Interesting effect here.  The can itself is intriguing, but the mismatched boots on the worked in the background immediately attracts the eye. Very clever capture even if unintended.', '2009-12-17 21:22:29.000000', NULL, 1),
(5770785, 839252, 101256, '<td valign="top">Sometimes you just don''t want to say anything because anything you could say would pale in comparision to the original viewer impact. An exceptional image - well done.</td>', 'Sometimes you just don''t want to say anything because anything you could say would pale in comparision to the original viewer impact. An exceptional image - well done.', '2009-12-17 21:30:08.000000', NULL, 1),
(5770787, 840149, 101256, '<td valign="top">A poignant image of life on the street. The image seems a little under exposed but that adds to it''s overall impact and drama. I might have picked a little closer look and/or crop, but it''s very well done as it is. Great capture and should place high in the competition.</td>', 'A poignant image of life on the street. The image seems a little under exposed but that adds to it''s overall impact and drama. I might have picked a little closer look and/or crop, but it''s very well done as it is. Great capture and should place high in the competition.', '2009-12-17 21:32:40.000000', NULL, 1),
(5770790, 839377, 101256, '<td valign="top">An interesting title as the gargoyle is mythically supposed to be an eternal "watcher" if you will - so a bored gargoyle would have to have been very old indeed.  Interesting take.  An efficient and competant converison and capture.</td>', 'An interesting title as the gargoyle is mythically supposed to be an eternal "watcher" if you will - so a bored gargoyle would have to have been very old indeed.  Interesting take.  An efficient and competant converison and capture.', '2009-12-17 21:35:19.000000', NULL, 1),
(5770792, 840147, 101256, '<td valign="top">This is a technique that either works or doesn''t work.  In this case, it''s somewhat right in the middle. The rather washed out effect of the background and the sharp detailed green do work together, but I don''t have a sense of wow - as in wow factor when viewing the image. Technically, its ok certainly, but it just doesn''t have a positive effect on me.</td>', 'This is a technique that either works or doesn''t work.  In this case, it''s somewhat right in the middle. The rather washed out effect of the background and the sharp detailed green do work together, but I don''t have a sense of wow - as in wow factor when viewing the image. Technically, its ok certainly, but it just doesn''t have a positive effect on me.', '2009-12-17 21:37:26.000000', NULL, 1),
(5770794, 839080, 101256, '<td valign="top">Get into trouble what else.  A very nice capture - you can almost feel the cat thinking - well, what''s it going to be - the table or the countertop. Very nicely done.</td>', 'Get into trouble what else.  A very nice capture - you can almost feel the cat thinking - well, what''s it going to be - the table or the countertop. Very nicely done.', '2009-12-17 21:38:25.000000', NULL, 1),
(5770801, 839925, 85866, '<td valign="top">Beautifully captured study of polite boredom ... well done</td>', 'Beautifully captured study of polite boredom ... well done', '2009-12-17 21:51:50.000000', NULL, 1),
(5770802, 839950, 85866, '<td valign="top">I like the use of dof ... capturing sharp and blurred boredom</td>', 'I like the use of dof ... capturing sharp and blurred boredom', '2009-12-17 21:54:03.000000', NULL, 1),
(5770819, 839388, 101256, '<td valign="top">Very intersting macro and I really like the reflected image concept. Nice capture.</td>', 'Very intersting macro and I really like the reflected image concept. Nice capture.', '2009-12-17 22:10:10.000000', NULL, 1),
(5770820, 840045, 101256, '<td valign="top">A boring picture denoting boring image - not bad - not bad at all. I like it.</td>', 'A boring picture denoting boring image - not bad - not bad at all. I like it.', '2009-12-17 22:10:45.000000', NULL, 1),
(5770821, 840026, 101256, '<td valign="top">This is interesting - I don''t see this as boredom as much as I see it as peaceful repose comtemplating nothing in a comfortable place and at a comfortable time. It''s a hard image to rate with that in mind with respect to the subject challenge. Technically excellant and a great conversion. I''d like to rate this high for it''s artistic components so...I will.  Well done.</td>', 'This is interesting - I don''t see this as boredom as much as I see it as peaceful repose comtemplating nothing in a comfortable place and at a comfortable time. It''s a hard image to rate with that in mind with respect to the subject challenge. Technically excellant and a great conversion. I''d like to rate this high for it''s artistic components so...I will.  Well done.', '2009-12-17 22:13:27.000000', NULL, 1),
(5770822, 839702, 101256, '<td valign="top">This is laugh out loud funny.  Excellant - a most welcome respite from some of the images in this challenge. Well done.</td>', 'This is laugh out loud funny.  Excellant - a most welcome respite from some of the images in this challenge. Well done.', '2009-12-17 22:14:30.000000', NULL, 1),
(5770823, 840083, 101256, '<td valign="top">I had to come back to this to get the concept. Nicely done.</td>', 'I had to come back to this to get the concept. Nicely done.', '2009-12-17 22:15:21.000000', NULL, 1),
(5770826, 838609, 101256, '<td valign="top">Very clever and an excellant demonstration of time lapse. From a technical standpoint, it''s wonderful and very competant. Technically, the very light use of color is a plus.  Artistically hits every button.  Well done - should be a ribbon contender if not a winner.</td>', 'Very clever and an excellant demonstration of time lapse. From a technical standpoint, it''s wonderful and very competant. Technically, the very light use of color is a plus.  Artistically hits every button.  Well done - should be a ribbon contender if not a winner.', '2009-12-17 22:16:59.000000', NULL, 1),
(5770829, 840078, 101256, '<td valign="top">Another interesting candid capture - the slight grain enhances the over all effect and the angle is very different and intriguing. Well done.</td>', 'Another interesting candid capture - the slight grain enhances the over all effect and the angle is very different and intriguing. Well done.', '2009-12-17 22:18:09.000000', NULL, 1),
(5770831, 839986, 101256, '<td valign="top">ROTFL!! Well done.  Should be a winner just for the humor content. Excellant.</td>', 'ROTFL!! Well done.  Should be a winner just for the humor content. Excellant.', '2009-12-17 22:18:52.000000', NULL, 1),
(5770835, 840053, 101256, '<td valign="top">My favorite Christmas movie written by a good friend of my father in fact. A great homage although I fear not enough people will have seen the movie to appreciate the concept.  I do however and it''s a ten for you. :&gt;)</td>', 'My favorite Christmas movie written by a good friend of my father in fact. A great homage although I fear not enough people will have seen the movie to appreciate the concept.  I do however and it''s a ten for you. :>)', '2009-12-17 22:20:29.000000', NULL, 1),
(5770836, 839258, 101256, '<td valign="top">A great candid image and so very true.  After spending enough time on post duty, it can be reall and truly incredibly boring.  Nice capture.</td>', 'A great candid image and so very true.  After spending enough time on post duty, it can be reall and truly incredibly boring.  Nice capture.', '2009-12-17 22:21:21.000000', NULL, 1),
(5770849, 839808, 101256, '<td valign="top">Why does this image remind me of something out of "Clockwork Orange"? There is an inherent feel of great menace here rather than boredom. Still, it''s a great capture - well done.</td>', 'Why does this image remind me of something out of "Clockwork Orange"? There is an inherent feel of great menace here rather than boredom. Still, it''s a great capture - well done.', '2009-12-17 22:29:27.000000', NULL, 1),
(5770850, 840084, 101256, '<td valign="top">Well done - this is a great image. I imagine one could fine a commmercial use for this image it''s that good convering the challenge subject matter.  Should place high if not a ribbon.</td>', 'Well done - this is a great image. I imagine one could fine a commmercial use for this image it''s that good convering the challenge subject matter.  Should place high if not a ribbon.', '2009-12-17 22:30:41.000000', NULL, 1),
(5770855, 840145, 101256, '<td valign="top">I wasn''t sure what to think about this and kept coming back to it to get a feel for what the author was trying to convey. It doesn''t seem to me that the subject is bored - it comes across more as merely killing time or listening to instructions.  It is technically an excellant conversion though - artistically sound. A good solid capture.</td>', 'I wasn''t sure what to think about this and kept coming back to it to get a feel for what the author was trying to convey. It doesn''t seem to me that the subject is bored - it comes across more as merely killing time or listening to instructions.  It is technically an excellant conversion though - artistically sound. A good solid capture.', '2009-12-17 22:34:12.000000', NULL, 1),
(5770859, 838579, 101256, '<td valign="top">Four attempts to interpret this and I think I finally got the idea - a boring facade.  Took a while, but that''s my impression of what the author is trying to convey here.  As such, it works well, but it takes a while to get the point across - at least to me.  Well done.</td>', 'Four attempts to interpret this and I think I finally got the idea - a boring facade.  Took a while, but that''s my impression of what the author is trying to convey here.  As such, it works well, but it takes a while to get the point across - at least to me.  Well done.', '2009-12-17 22:36:10.000000', NULL, 1),
(5771104, 839252, 5364, '<td valign="top">I think your title displays more impatience than boredom, but the image certainly captures a bored expression well.</td>', 'I think your title displays more impatience than boredom, but the image certainly captures a bored expression well.', '2009-12-18 05:34:09.000000', NULL, 1),
(5771105, 838574, 5364, '<td valign="top">I don''t think it meets the challenge in any way, but giving you a comment on the picture.. The bug is well captured, but I find the bright background too overwhelming and therefore distracting.</td>', 'I don''t think it meets the challenge in any way, but giving you a comment on the picture.. The bug is well captured, but I find the bright background too overwhelming and therefore distracting.', '2009-12-18 05:38:52.000000', NULL, 1),
(5771106, 839720, 5364, '<td valign="top">I don''t think you''ve captured boredom, as the hammer and cracked screen speak too strongly of anger. I do like the point of view you''ve chosen though.</td>', 'I don''t think you''ve captured boredom, as the hammer and cracked screen speak too strongly of anger. I do like the point of view you''ve chosen though.', '2009-12-18 05:42:13.000000', NULL, 1),
(5771107, 839449, 5364, '<td valign="top">I like this a lot. The tones are excellent and for me the composition is just right</td>', 'I like this a lot. The tones are excellent and for me the composition is just right', '2009-12-18 05:43:28.000000', NULL, 1),
(5771108, 840076, 5364, '<td valign="top">A marvellous image. the tones and composition appeal to me a lot. I just don''t see what you gain by adding that border though</td>', 'A marvellous image. the tones and composition appeal to me a lot. I just don''t see what you gain by adding that border though', '2009-12-18 05:48:59.000000', NULL, 1),
(5771153, 840145, 5364, '<td valign="top">I would really like to hear why you put this border onto an otherwise excellent image. To me it looks like your subject is wearing a very wide hat.</td>', 'I would really like to hear why you put this border onto an otherwise excellent image. To me it looks like your subject is wearing a very wide hat.', '2009-12-18 07:28:11.000000', NULL, 1),
(5771169, 840025, 71239, '<td valign="top">A lot of pet shots in this challenge, but this one hits the mark.  Expression spot on, the textures in the hair and seat are great and colour tones blend well.  DOF nice as having all the body in focus would take the eye away from the face.</td>', 'A lot of pet shots in this challenge, but this one hits the mark.  Expression spot on, the textures in the hair and seat are great and colour tones blend well.  DOF nice as having all the body in focus would take the eye away from the face.', '2009-12-18 08:08:07.000000', NULL, 1),
(5771170, 840081, 71239, '<td valign="top">It''s the boxes that make the shot, really gives the impression of dull uniformity to match the model''s expression.  Great shot.</td>', 'It''s the boxes that make the shot, really gives the impression of dull uniformity to match the model''s expression.  Great shot.', '2009-12-18 08:09:28.000000', NULL, 1),
(5771174, 840078, 71239, '<td valign="top">Dark and moody street shot and nice lines with the steps.  Choosing a shot with him looking out of frame works well, adds to the detachment and boredom of the pose.</td>', 'Dark and moody street shot and nice lines with the steps.  Choosing a shot with him looking out of frame works well, adds to the detachment and boredom of the pose.', '2009-12-18 08:11:40.000000', NULL, 1),
(5771178, 839258, 71239, '<td valign="top">Great horizontal and vertical elements in the shot and perfect positioning of the guard in the frame.  Love the slumped posture and the overall shot works great in monochrome.<br/> <br/>One of the few stand out shots.</td>', 'Great horizontal and vertical elements in the shot and perfect positioning of the guard in the frame.  Love the slumped posture and the overall shot works great in monochrome. One of the few stand out shots.', '2009-12-18 08:14:52.000000', NULL, 1),
(5771179, 839950, 71239, '<td valign="top">Great main subject and the yawning secondary subject.  Just right to crop along the left hand edge where you did, just letting us see enough of the railway platform and lines whilst keeping the bright sky to a minimum.<br/>Top shot.</td>', 'Great main subject and the yawning secondary subject.  Just right to crop along the left hand edge where you did, just letting us see enough of the railway platform and lines whilst keeping the bright sky to a minimum.Top shot.', '2009-12-18 08:16:56.000000', NULL, 1),
(5771183, 840084, 71239, '<td valign="top">Fantastic retro feel to the shot.  Both poses are perfect and I love the slight rebellious look to the boy with a smart shirt ("my mother made me wear this") but the casual trainers and white socks.<br/>Great crop on the right, allowing some depth to show but pegging the eye to the front with the table and glass.<br/>The image as a whole tells the story, no title required.  That''s my measure of a great photo.</td>', 'Fantastic retro feel to the shot.  Both poses are perfect and I love the slight rebellious look to the boy with a smart shirt ("my mother made me wear this") but the casual trainers and white socks.Great crop on the right, allowing some depth to show but pegging the eye to the front with the table and glass.The image as a whole tells the story, no title required.  That''s my measure of a great photo.', '2009-12-18 08:22:04.000000', NULL, 1),
(5771191, 839838, 71239, '<td valign="top">Great expression and high key is very effective at both concentrating the eye to the face and adding to the sense that all around is dull uniformity.  One of my top picks in this challenge.</td>', 'Great expression and high key is very effective at both concentrating the eye to the face and adding to the sense that all around is dull uniformity.  One of my top picks in this challenge.', '2009-12-18 08:24:32.000000', NULL, 1),
(5771207, 840080, 71239, '<td valign="top">Love the extra dimension this shot has over the other "bored person" shots here.  Absolutely right to crop off the eyes, the posture and mouth give the expression and the eyes are drawn to the jewellery which in turn gives us the story.<br/>A creative take on the challenge that deserves a high mark.</td>', 'Love the extra dimension this shot has over the other "bored person" shots here.  Absolutely right to crop off the eyes, the posture and mouth give the expression and the eyes are drawn to the jewellery which in turn gives us the story.A creative take on the challenge that deserves a high mark.', '2009-12-18 08:28:35.000000', NULL, 1),
(5771225, 839254, 71239, '<td valign="top">I would have liked to see more of the yawn by having the viewpoint much lower and with a bit more depth of field, as it is I can''t really tell that it''s a really big yawn as alluded to in the image.  The nose and snout are nicely sharp with the exposure handled well.</td>', 'I would have liked to see more of the yawn by having the viewpoint much lower and with a bit more depth of field, as it is I can''t really tell that it''s a really big yawn as alluded to in the image.  The nose and snout are nicely sharp with the exposure handled well.', '2009-12-18 08:38:07.000000', NULL, 1),
(5771230, 839856, 71239, '<td valign="top">Bear and chair stand out nicely and the floor/wall line is well positioned.  Technicals are fine too, but I''m afraid you''ve lost me with the title ("what''s the time Mr Wolf" is the only thing that comes to mind) and the challenge connection.</td>', 'Bear and chair stand out nicely and the floor/wall line is well positioned.  Technicals are fine too, but I''m afraid you''ve lost me with the title ("what''s the time Mr Wolf" is the only thing that comes to mind) and the challenge connection.', '2009-12-18 08:41:41.000000', NULL, 1),
(5771233, 838574, 71239, '<td valign="top">Great looking bug, maybe a bit closer and the viewpoint more in profile to get rid of the bright background above and to the left?  There''s potential here as a bug shot, but I''m no good at reading bug expressions so the "Bored" angle is eluding me a bit.</td>', 'Great looking bug, maybe a bit closer and the viewpoint more in profile to get rid of the bright background above and to the left?  There''s potential here as a bug shot, but I''m no good at reading bug expressions so the "Bored" angle is eluding me a bit.', '2009-12-18 08:45:08.000000', NULL, 1),
(5771235, 839714, 71239, '<td valign="top">I''d like to see more of the face and hence the expression that would convey more of the "Bored" aspect.  Unfortunately poor technicals (low resolution, white balance) and harsh lighting are letting this shot down.</td>', 'I''d like to see more of the face and hence the expression that would convey more of the "Bored" aspect.  Unfortunately poor technicals (low resolution, white balance) and harsh lighting are letting this shot down.', '2009-12-18 08:49:05.000000', NULL, 1),
(5771237, 838989, 71239, '<td valign="top">Like the framing, light and the single white goose as the main subject amongst the others, but the image theme to me is more one of "confused" than "bored" (and the title seems to be suggesting that as well).</td>', 'Like the framing, light and the single white goose as the main subject amongst the others, but the image theme to me is more one of "confused" than "bored" (and the title seems to be suggesting that as well).', '2009-12-18 08:52:48.000000', NULL, 1),
(5771244, 839983, 71239, '<td valign="top">Sorry, I''m going to need some stronger hints in the image to link title and photo together and get the story here.</td>', 'Sorry, I''m going to need some stronger hints in the image to link title and photo together and get the story here.', '2009-12-18 09:01:31.000000', NULL, 1),
(5771246, 839529, 71239, '<td valign="top">Nicely blurred stem and muted background, but the focus isn''t as sharp as I''d like on the main flower and the noise in the shot is a bit distracting.  I''m also struggling to see the connection to the challenge.  Sorry.</td>', 'Nicely blurred stem and muted background, but the focus isn''t as sharp as I''d like on the main flower and the noise in the shot is a bit distracting.  I''m also struggling to see the connection to the challenge.  Sorry.', '2009-12-18 09:03:45.000000', NULL, 1),
(5771249, 839209, 71239, '<td valign="top">I like the framing of the pigeon, but the uniform light sky is unfortunate and the link to the challenge eludes me.  Sorry.</td>', 'I like the framing of the pigeon, but the uniform light sky is unfortunate and the link to the challenge eludes me.  Sorry.', '2009-12-18 09:06:01.000000', NULL, 1),
(5771355, 839080, 71239, '<td valign="top">A pity the detail has been lost in the fur along the cheek bone and the leg - these areas have gone to solid black.  The focal plane seems right from the blankets but the cat itself could be sharper which is surprising @ 1/200sec.  Did it move just as you were taking the shot?</td>', 'A pity the detail has been lost in the fur along the cheek bone and the leg - these areas have gone to solid black.  The focal plane seems right from the blankets but the cat itself could be sharper which is surprising @ 1/200sec.  Did it move just as you were taking the shot?', '2009-12-18 10:50:17.000000', NULL, 1),
(5771361, 839377, 71239, '<td valign="top">Sharp and well exposed main subject.  I would have been tempted to put it where you could see something going on in the background (e.g. hints of a party or some other activity) so that there is a bit more of a story to the shot and some context as to why the gargoyle might be bored.</td>', 'Sharp and well exposed main subject.  I would have been tempted to put it where you could see something going on in the background (e.g. hints of a party or some other activity) so that there is a bit more of a story to the shot and some context as to why the gargoyle might be bored.', '2009-12-18 10:56:17.000000', NULL, 1),
